import { TimeseriesVariantSlotProps } from '../../../../types/timeseries.js';
import { getDatapointTime } from '../../../../utils/timeseries.js';

/**
 * Returns the percentage the input value represents from the total.
 * @param value - given value
 * @param total - given total sum of values
 * @param allowNegativeValues
 * @returns
 */
export function getRelativeValue(
  value: number,
  total: number,
  allowNegativeValues: boolean = true,
) {
  if (total === 0) {
    return 0;
  }

  const currentValue = allowNegativeValues ? value : Math.abs(value);

  return Math.floor((currentValue / total) * 1000) / 10; // move the comma by 3 places before flooring to keep precision
}

/**
 * Group the accumulation of values of datapoints by start timestamp.
 * @param timeseries - given TimeseriesVariantSlotProps[]
 * @returns - map of accumulated values by timestamp
 */
export function groupValueByTimestamp(
  timeseries: TimeseriesVariantSlotProps[],
): Map<number, number> {
  const map = new Map<number, number>();
  for (const series of timeseries) {
    for (const datapoint of series.datapoints) {
      const key = getDatapointTime(
        datapoint.start,
        datapoint.end,
        datapoint.center,
      );
      const value = map.get(key) ?? 0;

      map.set(key, value + Math.abs(datapoint.value));
    }
  }

  return map;
}
